import{_ as a,o as l,c as r,a5 as t}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"图片透视变换工具","description":"","frontmatter":{"标题":"917-图片透视变换工具(功能上对某些复杂图片并不精确)","日期":"2026-08-08T00:00:00.000Z","修改日期":"2026-08-09T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["opencv","PyQt5","图像处理","图像矫正","图片处理工具","图片透视变换","文档矫正","透视矫正"]},"headers":[{"level":2,"title":"工具简介","slug":"工具简介","link":"#工具简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"自动识别四边形区域","slug":"自动识别四边形区域","link":"#自动识别四边形区域","children":[]},{"level":3,"title":"多区域同时显示与切换","slug":"多区域同时显示与切换","link":"#多区域同时显示与切换","children":[]},{"level":3,"title":"控制点拖动微调","slug":"控制点拖动微调","link":"#控制点拖动微调","children":[]},{"level":3,"title":"滚轮缩放预览","slug":"滚轮缩放预览","link":"#滚轮缩放预览","children":[]},{"level":3,"title":"实时预览变换效果","slug":"实时预览变换效果","link":"#实时预览变换效果","children":[]},{"level":3,"title":"旋转角度矫正","slug":"旋转角度矫正","link":"#旋转角度矫正","children":[]},{"level":3,"title":"矩形宽高与整体移动","slug":"矩形宽高与整体移动","link":"#矩形宽高与整体移动","children":[]},{"level":3,"title":"一键透视变换并自动保存","slug":"一键透视变换并自动保存","link":"#一键透视变换并自动保存","children":[]},{"level":3,"title":"多种方式打开图片","slug":"多种方式打开图片","link":"#多种方式打开图片","children":[]},{"level":3,"title":"中文路径与高清原图处理","slug":"中文路径与高清原图处理","link":"#中文路径与高清原图处理","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：打开图片","slug":"第一步-打开图片","link":"#第一步-打开图片","children":[]},{"level":3,"title":"第二步：调整控制点","slug":"第二步-调整控制点","link":"#第二步-调整控制点","children":[]},{"level":3,"title":"第三步：调整旋转角度并执行变换","slug":"第三步-调整旋转角度并执行变换","link":"#第三步-调整旋转角度并执行变换","children":[]},{"level":3,"title":"演示视频","slug":"演示视频","link":"#演示视频","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0（2026-08-07）","slug":"v1-0-2026-08-07","link":"#v1-0-2026-08-07","children":[]}]}],"relativePath":"md/图片批处理/917-图片透视变换工具(功能上对某些复杂图片并不精确).md","filePath":"md/图片批处理/917-图片透视变换工具(功能上对某些复杂图片并不精确).md"}'),i={name:"md/图片批处理/917-图片透视变换工具(功能上对某些复杂图片并不精确).md"};function n(h,e,o,b,d,s){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="图片透视变换工具" tabindex="-1">图片透视变换工具 <a class="header-anchor" href="#图片透视变换工具" aria-label="Permalink to &quot;图片透视变换工具&quot;">​</a></h1><blockquote><p>基于 OpenCV 的图片透视变换工具，通过 4 个控制点将拍摄倾斜、变形的图片（文档、名片、票据等）矫正为正面视图，支持自动识别多个四边形区域、控制点拖动微调与滚轮缩放预览，一键执行透视变换并自动保存矫正结果。</p></blockquote><h2 id="工具简介" tabindex="-1">工具简介 <a class="header-anchor" href="#工具简介" aria-label="Permalink to &quot;工具简介&quot;">​</a></h2><p>本工具用于将拍摄倾斜、透视变形的图片矫正为正面视图。用手机或相机拍摄文档、名片、票据、展板等场景时，由于拍摄角度倾斜，画面中的物体往往呈现梯形或任意四边形变形，本工具通过指定（或自动识别）图片中的 4 个角点，利用透视变换将选中区域拉正为矩形，输出清晰、端正的矫正结果。</p><p>图片加载后自动适配显示，可通过滚轮缩放预览细节；支持一键自动识别图中多个四边形区域（如多张票据、多张名片并排拍摄的场景），识别后点击任意区域的控制点即可切换变换目标；控制点可随时拖动微调，确认后执行变换并自动弹出保存对话框，默认保存为「原文件名_zh.扩展名」到原图目录。</p><p>所有图像处理均在原图分辨率上执行，界面显示的大图仅为预览缩放，矫正结果不损失原始清晰度；同时全面兼容中文路径，支持 jpg、jpeg、png、bmp、gif、webp、tif、tiff 等常见图片格式。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/08/image.png" alt=""></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="自动识别四边形区域" tabindex="-1">自动识别四边形区域 <a class="header-anchor" href="#自动识别四边形区域" aria-label="Permalink to &quot;自动识别四边形区域&quot;">​</a></h3><p>— 基于自适应 Canny 边缘检测与闭运算连接断裂边缘，对明暗不同的图片自动计算阈值，无需手动调参；<br> — 同时用 Otsu 二值化（明暗两个方向）检测主体与背景分离明显的区域，与边缘检测互补；<br> — 轮廓面积占比小于 2% 的噪声自动过滤，接近整图边界的轮廓（照片/文档边缘）自动排除；<br> — 候选区域按「主体内部与外部背景色差」降序排列，主体与背景颜色对比越明显越优先命中；<br> — 多级 epsilon 逐步逼近四边形，边缘不完整时用凸包填补凹陷，旋转矩形兜底，提高识别命中率；<br> — 一次识别可同时输出多个四边形区域，适合多张票据、名片并排拍摄的场景。</p><h3 id="多区域同时显示与切换" tabindex="-1">多区域同时显示与切换 <a class="header-anchor" href="#多区域同时显示与切换" aria-label="Permalink to &quot;多区域同时显示与切换&quot;">​</a></h3><p>— 识别出的多个区域全部显示在画布上，各自用不同颜色区分；<br> — 激活区域为红色实线实心点，非激活区域为半透明虚线空心点；<br> — 点击任意区域的控制点即可切换激活区域，状态栏同步提示当前区域序号。</p><h3 id="控制点拖动微调" tabindex="-1">控制点拖动微调 <a class="header-anchor" href="#控制点拖动微调" aria-label="Permalink to &quot;控制点拖动微调&quot;">​</a></h3><p>— 选区以矩形形式构建：4 个角点（圆点）与 4 条边构成完整矩形框，仅绘制四条边线、不显示交叉对角线；<br> — 每个角点带 1-4 编号，按住左键拖动即可微调位置，支持任意四边形调整；<br> — 鼠标悬停到角点上自动变为可拖拽光标，悬停到上/下边中点显示垂直双向箭头、左/右边中点显示水平双向箭头，提示可调整方向；<br> — 12 像素命中容差，点击精确；优先检测激活区域，避免重叠区域无法拖动。</p><h3 id="滚轮缩放预览" tabindex="-1">滚轮缩放预览 <a class="header-anchor" href="#滚轮缩放预览" aria-label="Permalink to &quot;滚轮缩放预览&quot;">​</a></h3><p>— 滚轮以鼠标位置为锚点缩放，缩放范围 0.1 至 5 倍；<br> — 控制点始终保持固定屏幕大小，缩放后仍然清晰可见、便于精确对齐。</p><h3 id="实时预览变换效果" tabindex="-1">实时预览变换效果 <a class="header-anchor" href="#实时预览变换效果" aria-label="Permalink to &quot;实时预览变换效果&quot;">​</a></h3><p>— 右侧预览区实时显示当前激活区域的透视变换结果，拖动控制点、调整矩形或切换区域后即时刷新，所见即所得；<br> — 预览基于显示用图计算，操作流畅，正式保存时仍以原图分辨率输出。</p><h3 id="旋转角度矫正" tabindex="-1">旋转角度矫正 <a class="header-anchor" href="#旋转角度矫正" aria-label="Permalink to &quot;旋转角度矫正&quot;">​</a></h3><p>— 支持手动输入旋转角度（-180° 至 180°，精确到 0.1°），先旋转图片再执行透视变换；<br> — 旋转后左侧画布图片与控制点同步旋转、所见即所得，可直接在旋转后的图上继续拖动微调；<br> — 适合拍摄时画面整体倾斜的图片，先旋转矫正水平方向，再框选目标区域拉正；<br> — 旋转采用扩边方式保留图片全部内容，空白区域以白色填充，修改角度后实时预览即时反馈；<br> — 提供「归零」按钮一键恢复 0°，新打开图片时旋转角度自动归零。</p><h3 id="矩形宽高与整体移动" tabindex="-1">矩形宽高与整体移动 <a class="header-anchor" href="#矩形宽高与整体移动" aria-label="Permalink to &quot;矩形宽高与整体移动&quot;">​</a></h3><p>— 矩形宽度、高度输入框实时同步当前区域宽高，修改后以区域中心为锚点整体缩放控制点；<br> — 提供上下左右方向按钮，可整体平移矩形选区，支持按住连续移动；<br> — 拖动矩形上、下边中点可单独调整高度，拖动左、右边中点可单独调整宽度，实时反馈到预览；<br> — 与逐点拖动配合使用，可快速将选区调整到目标位置。</p><h3 id="一键透视变换并自动保存" tabindex="-1">一键透视变换并自动保存 <a class="header-anchor" href="#一键透视变换并自动保存" aria-label="Permalink to &quot;一键透视变换并自动保存&quot;">​</a></h3><p>— 执行变换针对当前激活区域，控制点坐标自动从显示坐标映射回原图坐标；<br> — 目标尺寸取上下边宽度、左右边高度的最大值，保证矫正结果不变形；<br> — 变换完成后自动弹出保存对话框，默认保存为「原文件名_zh.扩展名」到原图目录。</p><h3 id="多种方式打开图片" tabindex="-1">多种方式打开图片 <a class="header-anchor" href="#多种方式打开图片" aria-label="Permalink to &quot;多种方式打开图片&quot;">​</a></h3><p>— 工具栏「打开图片」按钮，通过文件对话框选择图片；<br> — 直接将图片拖入窗口任意位置（侧边栏、内容页、画布、窗口空白区域均可）。</p><h3 id="中文路径与高清原图处理" tabindex="-1">中文路径与高清原图处理 <a class="header-anchor" href="#中文路径与高清原图处理" aria-label="Permalink to &quot;中文路径与高清原图处理&quot;">​</a></h3><p>— 采用 imdecode / imencode 读写图片，全面兼容中文路径与中文文件名；<br> — 显示用图最大边长 800 像素，变换始终在原图分辨率执行，输出不损失清晰度。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/08/image-1.png" alt=""></p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-打开图片" tabindex="-1">第一步：打开图片 <a class="header-anchor" href="#第一步-打开图片" aria-label="Permalink to &quot;第一步：打开图片&quot;">​</a></h3><p>— 点击工具栏「打开图片」按钮，在弹出的对话框中选择图片（支持 jpg、jpeg、png、bmp、gif）；<br> — 或直接将图片文件拖入程序窗口任意区域（支持 jpg、jpeg、png、bmp、gif、webp、tif、tiff）；<br> — 打开成功后状态栏显示图片名称与分辨率，画布自动适配显示。</p><h3 id="第二步-调整控制点" tabindex="-1">第二步：调整控制点 <a class="header-anchor" href="#第二步-调整控制点" aria-label="Permalink to &quot;第二步：调整控制点&quot;">​</a></h3><p>— 加载图片后默认以图片四角为控制点（单区域），可直接执行变换；<br> — 如需矫正图中某个物体（如一张卡片），点击「自动识别点位」按钮自动检测四边形区域，多个区域会同时显示；<br> — 点击区域控制点切换当前变换区域，按住角点拖动微调位置，拖动边中点单独调整上下左右边缘，滚轮缩放查看细节；<br> — 在底部「矩形调整」栏直接修改宽度/高度，或以方向按钮整体平移选区，右侧实时预览即时反馈；<br> — 点击「重置」恢复默认的图片四角控制点。</p><h3 id="第三步-调整旋转角度并执行变换" tabindex="-1">第三步：调整旋转角度并执行变换 <a class="header-anchor" href="#第三步-调整旋转角度并执行变换" aria-label="Permalink to &quot;第三步：调整旋转角度并执行变换&quot;">​</a></h3><p>— 画面整体倾斜时，在「旋转角度」输入框手动输入角度值（范围 -180° 至 180°，支持小数点后一位，也可用上下箭头微调），右侧实时预览立即显示旋转后的效果；<br> — 旋转角度可在执行变换前任意修改，左侧画布图片与控制点同步旋转、随时可继续拖动微调；<br> — 调整好旋转角度与控制点后点击「执行变换」，程序先按角度旋转原图，再执行透视变换并弹出保存对话框；<br> — 默认保存位置为原图所在目录，默认文件名为「原文件名_zh.扩展名」，可自行修改保存位置与格式（jpg、jpeg、png、bmp）；<br> — 保存成功后状态栏显示完整保存路径。</p><h3 id="演示视频" tabindex="-1">演示视频 <a class="header-anchor" href="#演示视频" aria-label="Permalink to &quot;演示视频&quot;">​</a></h3><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 自动识别基于边缘检测，对低对比度、边缘模糊的图片可能识别不准，可切换为手动拖动控制点微调；<br> — 一次「执行变换」仅针对当前激活区域；多区域图片需逐区域切换并分别执行变换；<br> — 大图在界面中会自动缩放显示（最大边长 800 像素），变换输出始终为原图分辨率，预览缩放不影响结果；<br> — 变换结果目标尺寸取对边最大长度，保证矫正后的四边形为端正矩形。</p><p>待更新…..</p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-2026-08-07" tabindex="-1">v1.0（2026-08-07） <a class="header-anchor" href="#v1-0-2026-08-07" aria-label="Permalink to &quot;v1.0（2026-08-07）&quot;">​</a></h3><p>— 首版发布：基于 PyQt5 + OpenCV 的图片透视变换工具；<br> — 支持自动识别多个四边形区域，点击控制点切换变换区域；<br> — 选区以矩形形式构建，4 个角点与 4 条边中点均可拖动，支持单独调整上、下、左、右边缘宽高；<br> — 支持控制点拖动微调、滚轮缩放预览；<br> — 新增右侧实时预览，调整控制点或矩形时即时显示矫正效果；<br> — 新增矩形宽度/高度调整与上下左右整体移动；<br> — 新增旋转角度矫正：手动输入 -180° 至 180° 旋转角度，画布图片与控制点同步旋转，扩边保留全部内容，实时预览即时反馈；<br> — 矩形框仅绘制四条边线、不再显示交叉对角线；<br> — 悬停角点/边中点显示对应拖拽光标，上、下边垂直双向箭头，左、右边水平双向箭头；<br> — 自动识别优化：Otsu 二值化双通道检测、排除整图边界轮廓，主体与背景颜色对比越明显越优先命中；<br> — 支持一键透视变换并自动保存，默认「原文件名_zh.扩展名」；<br> — 支持窗口任意位置拖入图片，全面兼容中文路径。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3142.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3142.html</a></p>',45)])])}const u=a(i,[["render",n]]);export{c as __pageData,u as default};
